+import ognl.MemberAccess;
+
+import java.lang.reflect.Member;
+import java.lang.reflect.Modifier;
+import java.util.Arrays;
+import java.util.HashSet;
+import java.util.Map;
+import java.util.Set;
+
+/**
+ * A restrictive MemberAccess implementation that prevents OGNL injection attacks
+ * by blocking access to dangerous classes, static members, and getClass().
+ */
+class SafeMemberAccess implements MemberAccess {
+
+    private static final Set<String> BLOCKED_CLASSES = new HashSet<>(Arrays.asList(
+            "java.lang.Runtime",
+            "java.lang.ProcessBuilder",
+            "java.lang.System",
+            "java.lang.Class",
+            "java.lang.ClassLoader",
+            "java.lang.Thread",
+            "java.lang.ThreadGroup",
+            "java.lang.reflect.Method",
+            "java.lang.reflect.Field",
+            "java.lang.reflect.Constructor",
+            "java.io.File",
+            "java.io.FileInputStream",
+            "java.io.FileOutputStream",
+            "java.io.FileReader",
+            "java.io.FileWriter",
+            "java.net.URL",
+            "java.net.URLConnection",
+            "java.net.Socket",
+            "java.net.ServerSocket",
+            "javax.script.ScriptEngineManager",
+            "javax.script.ScriptEngine"
+    ));
+
+    private static final Set<String> BLOCKED_PACKAGES = new HashSet<>(Arrays.asList(
+            "java.lang.reflect.",
+            "java.lang.invoke.",
+            "java.io.",
+            "java.net.",
+            "java.nio.",
+            "javax.script.",
+            "javax.management.",
+            "ognl."
+    ));
+
+    @Override
+    public Object setup(Map context, Object target, Member member, String propertyName) {
+        return null;
+    }
+
+    @Override
+    public void restore(Map context, Object target, Member member, String propertyName, Object state) {
+    }
+
+    @Override
+    public boolean isAccessible(Map context, Object target, Member member, String propertyName) {
+        // Block static members to prevent access to static methods like Runtime.getRuntime()
+        if (Modifier.isStatic(member.getModifiers())) {
+            return false;
+        }
+
+        // Block getClass() to prevent class hierarchy traversal and classloader exploitation
+        if ("getClass".equals(member.getName())) {
+            return false;
+        }
+
+        // Block access to dangerous classes
+        Class<?> declaringClass = member.getDeclaringClass();
+        String className = declaringClass.getName();
+
+        if (BLOCKED_CLASSES.contains(className)) {
+            return false;
+        }
+
+        for (String blockedPackage : BLOCKED_PACKAGES) {
+            if (className.startsWith(blockedPackage)) {
+                return false;
+            }
+        }
+
+        return true;
+    }
+}

