+import java.util.HashSet;
+import java.util.Map;
+import java.util.Set;
+
+/**
+ * A restricted MemberAccess implementation that only allows access to
+ * getter methods and fields on whitelisted model classes, preventing
+ * OGNL injection attacks such as arbitrary code execution.
+ */
+public class SafeMemberAccess implements MemberAccess {
+
+    private static final Set<String> ALLOWED_PACKAGES = new HashSet<>(Arrays.asList(
+            "com.example.model"
+    ));
+
+    private static final Set<String> BLOCKED_CLASSES = new HashSet<>(Arrays.asList(
+            "java.lang.Runtime",
+            "java.lang.ProcessBuilder",
+            "java.lang.System",
+            "java.lang.Class",
+            "java.lang.ClassLoader",
+            "java.lang.Thread",
+            "java.lang.reflect.Method",
+            "java.lang.reflect.Field",
+            "java.lang.reflect.Constructor",
+            "java.io.File",
+            "java.io.InputStream",
+            "java.io.OutputStream",
+            "java.io.Reader",
+            "java.io.Writer",
+            "java.net.URL",
+            "java.net.URLConnection",
+            "java.net.Socket",
+            "java.net.ServerSocket",
+            "ognl.OgnlOps"
+    ));
+
+    @Override
+    public Object setup(Map context, Object target, Member member, String propertyName) {
+        return null;
+    }
+
+    @Override
+    public void restore(Map context, Object target, Member member, String propertyName, Object state) {
+    }
+
+    @Override
+    public boolean isAccessible(Map context, Object target, Member member, String propertyName) {
+        if (target == null || member == null) {
+            return false;
+        }
+
+        // Block all static member access to prevent @Class@method() calls
+        if (Modifier.isStatic(member.getModifiers())) {
+            return false;
+        }
+
+        Class<?> declaringClass = member.getDeclaringClass();
+
+        // Block access to dangerous classes
+        if (BLOCKED_CLASSES.contains(declaringClass.getName())) {
+            return false;
+        }
+
+        // Only allow access to classes in whitelisted packages
+        String packageName = declaringClass.getPackage() != null
+                ? declaringClass.getPackage().getName()
+                : "";
+
+        return ALLOWED_PACKAGES.contains(packageName);
+    }
+}

