+            className.startsWith("java.lang.System") ||
+            className.startsWith("java.lang.Class") ||
+            className.startsWith("java.lang.ClassLoader") ||
+            className.startsWith("java.lang.reflect") ||
+            className.startsWith("java.lang.Thread") ||
+            className.startsWith("java.io.File") ||
+            className.startsWith("java.net.Socket") ||
+            className.startsWith("javax.script")) {
+            throw new ClassNotFoundException("Access denied: " + className);
+        }
+
+        // Only allow classes from the application's own packages
+        if (!className.startsWith("com.example.")) {
+            throw new ClassNotFoundException("Only com.example classes are allowed: " + className);
+        }
+
+        return Class.forName(className);
+    }
+}
