+package com.example.service;
+
+import ognl.MemberAccess;
+
+import java.lang.reflect.Member;
+import java.lang.reflect.Modifier;
+import java.util.Arrays;
+import java.util.HashSet;
+import java.util.Map;
+import java.util.Set;
+
+/**
+ * A restricted MemberAccess implementation that prevents OGNL injection attacks
+ * by blocking static member access and only allowing access to safe, known classes.
+ */
+public class SafeMemberAccess implements MemberAccess {
+
+    private static final Set<String> ALLOWED_PACKAGES = new HashSet<>(Arrays.asList(
+            "com.example.model"
+    ));
+
+    private static final Set<Class<?>> ALLOWED_CLASSES = new HashSet<>(Arrays.asList(
+            Object.class,
+            String.class,
+            Boolean.class, boolean.class,
+            Integer.class, int.class,
+            Long.class, long.class,
+            Double.class, double.class,
+            Float.class, float.class,
+            Short.class, short.class,
+            Byte.class, byte.class,
+            Character.class, char.class
+    ));
+
+    @Override
+    public Object setup(Map context, Object target, Member member, String propertyName) {
+        return null;
+    }
+
+    @Override
+    public void restore(Map context, Object target, Member member, String propertyName, Object state) {
+    }
+
+    @Override
+    public boolean isAccessible(Map context, Object target, Member member, String propertyName) {
+        if (Modifier.isStatic(member.getModifiers())) {
+            return false;
+        }
+
+        Class<?> declaringClass = member.getDeclaringClass();
+
+        if (ALLOWED_CLASSES.contains(declaringClass)) {
+            return true;
+        }
+
+        if (declaringClass.getPackage() != null
+                && ALLOWED_PACKAGES.contains(declaringClass.getPackage().getName())) {
+            return true;
+        }
+
+        return false;
+    }
+}

