+package com.example.service;
+
+import ognl.MemberAccess;
+import ognl.Ognl;
+import ognl.OgnlContext;
+import ognl.OgnlException;
+
+import java.lang.reflect.Member;
+import java.lang.reflect.Modifier;
+import java.util.Arrays;
+import java.util.HashSet;
+import java.util.Map;
+import java.util.Set;
+
+public class ReportService {
+
+    private static final Set<String> BLOCKED_CLASSES = new HashSet<>(Arrays.asList(
+            "java.lang.Runtime",
+            "java.lang.ProcessBuilder",
+            "java.lang.System",
+            "java.lang.Class",
+            "java.lang.ClassLoader",
+            "java.lang.Thread",
+            "java.lang.reflect.Method",
+            "java.lang.reflect.Constructor",
+            "java.lang.reflect.Field"
+    ));
+
+    private static final MemberAccess RESTRICTED_MEMBER_ACCESS = new MemberAccess() {
+        @Override
+        public Object setup(Map context, Object target, Member member, String propertyName) {
+            return null;
+        }
+
+        @Override
+        public void restore(Map context, Object target, Member member, String propertyName, Object state) {
+        }
+
+        @Override
+        public boolean isAccessible(Map context, Object target, Member member, String propertyName) {
+            if (!Modifier.isPublic(member.getModifiers())) {
+                return false;
+            }
+            if (Modifier.isStatic(member.getModifiers())) {
+                return false;
+            }
+            if ("getClass".equals(member.getName())) {
+                return false;
+            }
+            String className = member.getDeclaringClass().getName();
+            if (BLOCKED_CLASSES.contains(className)) {
+                return false;
+            }
+            if (className.startsWith("java.lang.reflect.")) {
+                return false;
+            }
+            return true;
+        }
+    };
+
+    public Object getReportFieldValue(String expression, Object dataRoot) throws OgnlException {
+        if (expression == null || expression.isEmpty()) {
+            throw new OgnlException("Expression cannot be null or empty", null);
+        }
+        if (dataRoot == null) {
+            throw new OgnlException("Data root cannot be null", null);
+        }
+
+        Map context = Ognl.createDefaultContext(dataRoot, RESTRICTED_MEMBER_ACCESS);
+        Object parsedExpression = Ognl.parseExpression(expression);
+        return Ognl.getValue(parsedExpression, context, dataRoot);
+    }
+}
