+        Profile profile = new Profile("admin", true);
+        testUser = new User("John Doe", "john@example.com", profile);
+    }
+
+    @Test
+    public void testGetUserName() throws OgnlException {
+        Object result = reportService.getReportFieldValue("name", testUser);
+        assertEquals("John Doe", result);
+    }
+
+    @Test
+    public void testGetUserEmail() throws OgnlException {
+        Object result = reportService.getReportFieldValue("email", testUser);
+        assertEquals("john@example.com", result);
+    }
+
+    @Test
+    public void testGetProfileRole() throws OgnlException {
+        Object result = reportService.getReportFieldValue("profile.role", testUser);
+        assertEquals("admin", result);
+    }
+
+    @Test
+    public void testGetProfileActive() throws OgnlException {
+        Object result = reportService.getReportFieldValue("profile.active", testUser);
+        assertEquals(true, result);
+    }
+
+    @Test(expected = OgnlException.class)
+    public void testNullExpression() throws OgnlException {
+        reportService.getReportFieldValue(null, testUser);
+    }
+
+    @Test(expected = OgnlException.class)
+    public void testEmptyExpression() throws OgnlException {
+        reportService.getReportFieldValue("", testUser);
+    }
+
+    @Test(expected = OgnlException.class)
+    public void testNullDataRoot() throws OgnlException {
+        reportService.getReportFieldValue("name", null);
+    }
+}

